"use client";

import { useEffect, useRef } from "react";
import {
  AlertTriangle,
  ChevronDown,
  ChevronUp,
  CircleAlert,
  Info,
  Terminal,
  Trash2,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { ScrollArea } from "@/components/ui/scroll-area";
import { cn } from "@/lib/utils";
import type { ConsoleMessage } from "@/lib/sandbox/types";
import { formatTimestamp, sandboxPanelClassName } from "@/lib/sandbox/utils";

interface ConsolePanelProps {
  messages: ConsoleMessage[];
  onClear?: () => void;
  collapsed?: boolean;
  onCollapsedChange?: (collapsed: boolean) => void;
  className?: string;
}

const levelStyles: Record<
  ConsoleMessage["level"],
  { border: string; icon: typeof Terminal; iconClass: string }
> = {
  log: {
    border: "border-l-zinc-500",
    icon: Terminal,
    iconClass: "text-zinc-400",
  },
  info: {
    border: "border-l-sky-500",
    icon: Info,
    iconClass: "text-sky-400",
  },
  warn: {
    border: "border-l-amber-500",
    icon: AlertTriangle,
    iconClass: "text-amber-400",
  },
  error: {
    border: "border-l-red-500",
    icon: CircleAlert,
    iconClass: "text-red-400",
  },
};

export function ConsolePanel({
  messages,
  onClear,
  collapsed = false,
  onCollapsedChange,
  className,
}: ConsolePanelProps) {
  const bottomRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!collapsed) {
      bottomRef.current?.scrollIntoView({ behavior: "smooth" });
    }
  }, [messages, collapsed]);

  return (
    <div className={sandboxPanelClassName(className)}>
      <div className="flex items-center justify-between border-b border-white/[0.06] bg-[#101012] px-3 py-2">
        <div className="flex items-center gap-2">
          <Terminal className="size-3.5 text-zinc-500" />
          <span className="text-[11px] font-medium uppercase tracking-[0.12em] text-zinc-500">
            Console
          </span>
          <span className="rounded bg-muted px-1.5 py-0.5 font-mono text-[10px] text-muted-foreground">
            {messages.length}
          </span>
        </div>
        <div className="flex items-center gap-1">
          {onClear ? (
            <Button variant="ghost" size="xs" onClick={onClear}>
              <Trash2 />
              Clear
            </Button>
          ) : null}
          {onCollapsedChange ? (
            <Button
              variant="ghost"
              size="icon-xs"
              onClick={() => onCollapsedChange(!collapsed)}
              aria-label={collapsed ? "Expand console" : "Collapse console"}
            >
              {collapsed ? <ChevronUp /> : <ChevronDown />}
            </Button>
          ) : null}
        </div>
      </div>
      {!collapsed ? (
        <ScrollArea className="h-[180px] bg-[#09090b]">
          <div className="space-y-0.5 p-2 font-mono text-[11px]">
            {messages.length === 0 ? (
              <p className="px-2 py-6 text-center text-muted-foreground">
                No console output yet
              </p>
            ) : (
              messages.map((message) => {
                const style = levelStyles[message.level];
                const Icon = style.icon;
                return (
                  <div
                    key={message.id}
                    className={cn(
                      "flex items-start gap-2 rounded-md border-l-2 bg-muted/10 px-2 py-1.5",
                      style.border
                    )}
                  >
                    <Icon className={cn("mt-0.5 size-3 shrink-0", style.iconClass)} />
                    <span className="shrink-0 text-muted-foreground">
                      {formatTimestamp(message.timestamp)}
                    </span>
                    {message.source ? (
                      <span className="shrink-0 text-muted-foreground/70">
                        [{message.source}]
                      </span>
                    ) : null}
                    <span className="min-w-0 break-all text-foreground/90">
                      {message.message}
                    </span>
                  </div>
                );
              })
            )}
            <div ref={bottomRef} />
          </div>
        </ScrollArea>
      ) : null}
    </div>
  );
}

export type ViewportSize = "desktop" | "tablet" | "mobile";
export type ConsoleLevel = "log" | "info" | "warn" | "error";
export type PreviewStatus = "idle" | "loading" | "ready" | "error";

export interface SandboxFile {
  id: string;
  name: string;
  path: string;
  language: "tsx" | "ts" | "css" | "json";
  content: string;
  isDirty?: boolean;
}

export interface ConsoleMessage {
  id: string;
  level: ConsoleLevel;
  message: string;
  timestamp: Date;
  source?: string;
}

export interface PackageInstallEvent {
  id: string;
  name: string;
  version: string;
  status: "pending" | "success" | "error";
  output?: string;
}

export interface RuntimeError {
  title: string;
  message: string;
  stack: string;
  file: string;
  line: number;
  column?: number;
}

export interface FileTreeNode {
  id: string;
  name: string;
  type: "file" | "folder";
  children?: FileTreeNode[];
  fileId?: string;
}

export interface SandboxState {
  files: SandboxFile[];
  originalContents: Record<string, string>;
  activeFileId: string;
  fileTree: FileTreeNode[];
  consoleMessages: ConsoleMessage[];
  installEvents: PackageInstallEvent[];
  runtimeError: RuntimeError | null;
  previewStatus: PreviewStatus;
  viewport: ViewportSize;
  previewSrcDoc: string;
  consoleCollapsed: boolean;
}

import type { FileTreeNode, SandboxFile } from "./types";

export function getLanguageLabel(language: SandboxFile["language"]): string {
  const labels: Record<SandboxFile["language"], string> = {
    tsx: "TypeScript React",
    ts: "TypeScript",
    css: "CSS",
    json: "JSON",
  };
  return labels[language];
}

export function getLanguageBadge(language: SandboxFile["language"]): string {
  const badges: Record<SandboxFile["language"], string> = {
    tsx: "TSX",
    ts: "TS",
    css: "CSS",
    json: "JSON",
  };
  return badges[language];
}

export function formatTimestamp(date: Date): string {
  return date.toLocaleTimeString("en-US", {
    hour12: false,
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
  });
}

export function formatCode(content: string): string {
  const lines = content.split("\n");
  let indent = 0;
  const formatted: string[] = [];

  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed) {
      formatted.push("");
      continue;
    }

    if (/^[\}\]\)]/.test(trimmed)) {
      indent = Math.max(0, indent - 1);
    }

    formatted.push(`${"  ".repeat(indent)}${trimmed}`);

    const openBrackets = (trimmed.match(/[\{\[\(]/g) || []).length;
    const closeBrackets = (trimmed.match(/[\}\]\)]/g) || []).length;
    indent += openBrackets - closeBrackets;
    indent = Math.max(0, indent);
  }

  return formatted.join("\n");
}

export function findFileIdInTree(
  nodes: FileTreeNode[],
  fileId: string
): string | null {
  for (const node of nodes) {
    if (node.type === "file" && node.fileId === fileId) {
      return node.id;
    }
    if (node.children) {
      const found = findFileIdInTree(node.children, fileId);
      if (found) return found;
    }
  }
  return null;
}

export function removeFileFromTree(
  nodes: FileTreeNode[],
  fileId: string
): FileTreeNode[] {
  return nodes
    .filter((node) => !(node.type === "file" && node.fileId === fileId))
    .map((node) =>
      node.children
        ? { ...node, children: removeFileFromTree(node.children, fileId) }
        : node
    );
}

export function addFileToTree(
  nodes: FileTreeNode[],
  file: SandboxFile
): FileTreeNode[] {
  const parts = file.path.split("/");
  if (parts.length === 1) {
    return [
      ...nodes,
      {
        id: `tree-${file.id}`,
        name: file.name,
        type: "file" as const,
        fileId: file.id,
      },
    ];
  }

  const [folderName, ...rest] = parts;
  const folderId = `folder-${folderName}`;
  const existingFolderIndex = nodes.findIndex(
    (node) => node.type === "folder" && node.name === folderName
  );

  if (existingFolderIndex >= 0) {
    const folder = nodes[existingFolderIndex];
    const updatedFolder: FileTreeNode = {
      ...folder,
      children: addFileToTree(folder.children ?? [], {
        ...file,
        path: rest.join("/"),
      }),
    };
    return nodes.map((node, index) =>
      index === existingFolderIndex ? updatedFolder : node
    );
  }

  return [
    ...nodes,
    {
      id: folderId,
      name: folderName,
      type: "folder" as const,
      children: addFileToTree([], { ...file, path: rest.join("/") }),
    },
  ];
}

export function sandboxPanelClassName(className?: string): string {
  return [
    "overflow-hidden rounded-xl border border-white/[0.06] bg-[#101012]/90",
    className,
  ]
    .filter(Boolean)
    .join(" ");
}

export function getViewportWidth(viewport: "desktop" | "tablet" | "mobile") {
  const widths = {
    desktop: "100%",
    tablet: "768px",
    mobile: "390px",
  } as const;
  return widths[viewport];
}

export function formatRuntimeErrorForCopy(error: {
  title: string;
  message: string;
  stack: string;
  file: string;
  line: number;
  column?: number;
}): string {
  return `${error.title}: ${error.message}
at ${error.file}:${error.line}${error.column ? `:${error.column}` : ""}

${error.stack}`;
}
